#include <bits/stdc++.h>
using namespace std;

static char buf[1 << 16];
static size_t blen = 0, bpos = 0;
static inline int gc() {
    if (bpos == blen) {
        blen = fread(buf, 1, sizeof buf, stdin);
        bpos = 0;
        if (!blen) return -1;
    }
    return buf[bpos++];
}
static long long readLong() {
    int c = gc();
    while (c != '-' && (c < '0' || c > '9')) {
        if (c == -1) return 0;
        c = gc();
    }
    bool neg = false;
    if (c == '-') { neg = true; c = gc(); }
    long long v = 0;
    while (c >= '0' && c <= '9') { v = v * 10 + (c - '0'); c = gc(); }
    return neg ? -v : v;
}

int main() {
    long long n = readLong();
    int m = (int)readLong();
    long long p = 0, best = -1;
    for (long long i = 0; i < n; i++) {
        long long v = readLong();
        if (v > best) { best = v; p = i; }
    }
    // Each left rotation moves the maximum one place left (mod n); queries are independent.
    string out = to_string(m) + "\n";
