    fwrite(out.data(), 1, out.size(), stdout);
}

import java.io.*;

public class Main {
    static final InputStream in = System.in;
    static final byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;

    static int gc() throws IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = gc();
        while (c != '-' && (c < '0' || c > '9')) {
            if (c == -1) return 0;
            c = gc();
        }
        boolean neg = false;
        if (c == '-') { neg = true; c = gc(); }
        long v = 0;
        while (c >= '0' && c <= '9') { v = v * 10 + (c - '0'); c = gc(); }
        return neg ? -v : v;
    }

    public static void main(String[] args) throws IOException {
        long n = nextLong();
        int m = (int) nextLong();
        long p = 0, best = -1;
        for (long i = 0; i < n; i++) {
            long v = nextLong();
            if (v > best) { best = v; p = i; }
        }
        // Each left rotation moves the maximum one place left (mod n); queries are independent.
        StringBuilder out = new StringBuilder();
        out.append(m).append('\n');
        for (int i = 0; i < m; i++) {
            long r = nextLong();
            if (i > 0) out.append(' ');
            out.append(Math.floorMod(p - r, n));
        }
        out.append('\n');
        PrintStream ps = new PrintStream(new BufferedOutputStream(System.out, 1 << 16), false);
        ps.print(out);
        ps.flush();
    }
}

package main

import (
	"bufio"
	"os"
	"strconv"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<16)

func readInt() int64 {
	c, err := rd.ReadByte()
	for err == nil && c != '-' && (c < '0' || c > '9') {
		c, err = rd.ReadByte()
	}
	if err != nil {
		return 0
	}
	neg := false
	if c == '-' {
		neg = true
		c, err = rd.ReadByte()
	}
	var v int64
	for err == nil && c >= '0' && c <= '9' {
		v = v*10 + int64(c-'0')
		c, err = rd.ReadByte()
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	n := readInt()
	m := int(readInt())
	p, best := int64(0), int64(-1)
	for i := int64(0); i < n; i++ {
		if v := readInt(); v > best {
			best, p = v, i
		}
	}
	// Each left rotation moves the maximum one place left (mod n); queries are independent.
	out := strconv.AppendInt(nil, int64(m), 10)
	out = append(out, '\n')
	for i := 0; i < m; i++ {
		r := readInt()
		if i > 0 {
			out = append(out, ' ')
		}
		out = strconv.AppendInt(out, ((p-r)%n+n)%n, 10)
	}
	out = append(out, '\n')
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	w.Write(out)
}
